// Generated by vibelang from src/internal/FailureDetail.vibe; the migrate flow writes it again with each batch.
/**
 * What an alarm's failure log says beyond the failure's tag: enough to name
 * a failed schema migration and the database's answer, without quoting a
 * flow's content.
 *
 * A flow step's failure may quote a prompt or a provider, so for most
 * failures the log keeps the tag alone. A migration is different: its
 * statements and the server's answer to them are the engine's own schema
 * text. For a `MigrationError` the detail names the migration, the statement
 * that failed and the database's message. For any failure that reached the
 * database it names the SQL error's kind and SQLSTATE code, which carry no
 * content, and for a lost or refused connection the driver's text for it. A data exception (SQLSTATE class `22`) quotes the value it
 * rejected, so its message is left out even under a migration.
 *
 * @since 1.0.0
 */
import * as Tracer from "effect/Tracer";
import * as Cause from "effect/Cause";
import * as Effect from "effect/Effect";
import * as Exit from "effect/Exit";
/** How Effect's `Migrator` names a migration that failed. */
const failedMigration = /^Migration "([^"]+)" failed$/;
const sqlState = /^[0-9A-Z]{5}$/;
/** The longest statement or message the log keeps. */
const maxText = 1000;
/** How many client spans the recorder keeps: a failed statement's span is among the last few. */
const recentSpans = 16;
const asRecord = (value) => typeof value === "object" && value !== null ? value : undefined;
/** The error and each `cause` beneath it, outermost first, at most 8 deep. A `SqlError`'s `cause` is its reason. */
const chain = (error) => {
    const errors = [];
    for (let current = asRecord(error); current !== undefined && errors.length < 8; current = asRecord(current.cause)) {
        errors.push(current);
    }
    return errors;
};
/** Text the log may keep: credentials in a URL's user part removed, and cut to {@link maxText}. */
const text = (value) => value.replace(/([a-z][a-z0-9+.-]*:\/\/)[^\s/@]*@/gi, "$1<redacted>@").slice(0, maxText);
/**
 * The detail for a failed alarm's log line and span, from its `cause` and
 * `statement`, the text of the last SQL statement that failed during it
 * ({@link withFailedStatement}):
 *
 * - `db.error`: the SQL error's kind (`ConnectionError`, `SqlSyntaxError`, ...);
 * - `db.error.message`: for a `ConnectionError`, the driver's text for it
 *   (`PgConnection: Connection closed`), which carries no content;
 * - `db.response.status_code`: its SQLSTATE code;
 * - under a `MigrationError` only: `db.migration` (`<id>_<name>`),
 *   `db.migration.kind`, `error.message` (the migration error's own text),
 *   `db.error.message` (the database's message) and `db.query.text`
 *   (`statement`).
 *
 * @category telemetry
 * @since 1.0.0
 */
export const detail = (cause, statement) => {
    const errors = chain(Cause.squash(cause));
    const result = {};
    const sql = errors.findIndex((error) => error._tag === "SqlError");
    // The reason may be beyond the bounded chain.
    const reason = sql === -1 ? undefined : errors[sql + 1];
    if (reason !== undefined) {
        result["db.error"] = String(reason._tag);
        // A lost or refused connection's own text is the driver's ("PgConnection:
        // Connection closed", "PgConnection: Connection timed out"), never a row or
        // a statement, and it says which of those happened.
        if (reason._tag === "ConnectionError")
            result["db.error.message"] = text(String(reason.message));
    }
    const code = errors.map((error) => error.code).find((value) => typeof value === "string" && sqlState.test(value));
    if (code !== undefined)
        result["db.response.status_code"] = code;
    const quotesValue = code !== undefined && code.startsWith("22");
    const migration = errors.find((error) => error._tag === "MigrationError");
    if (migration === undefined)
        return result;
    const message = String(migration.message);
    result["error.message"] = text(message);
    const named = failedMigration.exec(message);
    if (named !== null)
        result["db.migration"] = named[1];
    result["db.migration.kind"] = String(migration.kind);
    // The innermost error is the database's own answer.
    if (sql !== -1 && !quotesValue)
        result["db.error.message"] = text(String(errors[errors.length - 1].message));
    if (statement !== undefined)
        result["db.query.text"] = text(statement);
    return result;
};
/**
 * Runs `effect` under the current tracer, keeping the last few client spans
 * it opens, and answers its exit with the text (`db.query.text`) of the last
 * SQL statement whose span ended in failure, if any. Every span still goes to
 * the current tracer unchanged.
 *
 * @category telemetry
 * @since 1.0.0
 */
export const withFailedStatement = (effect) => Effect.flatMap(Effect.tracer, (base) => {
    const recent = [];
    const tracer = Tracer.make({
        span(options) {
            const span = base.span(options);
            if (options.kind === "client") {
                recent.push(span);
                if (recent.length > recentSpans)
                    recent.shift();
            }
            return span;
        },
        context: base.context
    });
    return Effect.map(Effect.exit(Effect.withTracer(effect, tracer)), (exit) => {
        let statement;
        for (const span of recent) {
            const query = span.attributes.get("db.query.text");
            if (span.status._tag === "Ended" && Exit.isFailure(span.status.exit) && typeof query === "string") {
                statement = query;
            }
        }
        return [exit, statement];
    });
});
